import React, { useState, useContext, useEffect } from 'react';
import { Link as RouterLink, useNavigate, useLocation } from 'react-router-dom';
import {
  Container,
  Box,
  Typography,
  TextField,
  Button,
  Paper,
  Grid,
  Link,
  InputAdornment,
  IconButton,
  Alert,
  CircularProgress,
  Avatar,
  Divider,
  Stack,
} from '@mui/material';
import { Visibility, VisibilityOff, Lock, Email, PersonAdd } from '@mui/icons-material';
import useAuth from '../hooks/useAuth';
import AlertContext from '../context/alert/alertContext';

const Login = () => {
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    showPassword: false,
  });
  const { email, password, showPassword } = formData;
  const { login, loading, error } = useAuth();  // Destructure loading and error from useAuth
  const { setAlert } = useContext(AlertContext);
  const navigate = useNavigate();
  const location = useLocation();
  const from = location.state?.from?.pathname || '/dashboard';
  const handleSubmit = async (e) => {
  e.preventDefault();
  setLoading(true);
  
  if (email === '' || password === '') {
    setAlert('Please fill in all fields', 'error');
    setLoading(false);
    return;
  }
  try {
    const success = await login(email, password);
    if (success) {
      useEffect(() => {
        // Only run this effect if isAuthenticated changes to true
        if (isAuthenticated) {
          // Get the return URL from query parameters
          const queryParams = new URLSearchParams(window.location.search);
          const returnUrl = queryParams.get('returnUrl') || from;
          
          // Check if there's a session expired flag
          const sessionExpired = queryParams.get('sessionExpired') === 'true';
          
          if (sessionExpired) {
            setAlert('Your session has expired. Please log in again.', 'warning');
          }
          
          console.log('User is authenticated, navigating to:', returnUrl);
          // Use replace: true to prevent going back to login page
          navigate(returnUrl, { replace: true });
        }
      }, [isAuthenticated, navigate, from]);

      // Handle errors in a separate effect
      useEffect(() => {
        if (error) {
          setAlert(error, 'error');
          clearError();
        }
      }, [error, clearError, setAlert]);
    }
  } catch (err) {
    console.error('Login error:', err);
    setAlert(err.message || 'Login failed. Please try again.', 'error');
  } finally {
    setLoading(false);
  }
};
  // Pre-fill admin credentials for demo purposes (remove in production)
  const fillAdminCredentials = () => {
    setFormData({
      email: 'admin@pulsepoint.in',
      password: 'Admin@123',
    });
  };

  return (
    <Container component="main" maxWidth="xs">
      <Box
        sx={{
          marginTop: 8,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
        }}
      >
        <Typography component="h1" variant="h4" sx={{ mb: 3 }}>
          Welcome to PulsePoint
        </Typography>
        <Typography variant="body1" color="text.secondary" sx={{ mb: 4, textAlign: 'center' }}>
          Please sign in to continue to your dashboard
        </Typography>
        <Paper
          elevation={3}
          sx={{
            padding: 4,
            width: '100%',
            maxWidth: 450,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            width: '100%',
          }}
        >
          <Avatar sx={{ m: 1, bgcolor: 'primary.main' }}>
            <Lock />
          </Avatar>
          <Typography component="h1" variant="h5">
            Sign in to PulsePoint
          </Typography>
          
          <Box component="form" onSubmit={handleSubmit} sx={{ mt: 1, width: '100%' }}>
            <TextField
              margin="normal"
              required
              fullWidth
              id="email"
              label="Email Address"
              name="email"
              autoComplete="email"
              autoFocus
              value={email}
              onChange={handleChange}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Email color="action" />
                  </InputAdornment>
                ),
              }}
            />
            <TextField
              margin="normal"
              required
              fullWidth
              name="password"
              label="Password"
              type={showPassword ? 'text' : 'password'}
              id="password"
              autoComplete="current-password"
              value={password}
              onChange={handleChange}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Lock color="action" />
                  </InputAdornment>
                ),
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton
                      aria-label="toggle password visibility"
                      onClick={handleClickShowPassword}
                      edge="end"
                    >
                      {showPassword ? <VisibilityOff /> : <Visibility />}
                    </IconButton>
                  </InputAdornment>
                ),
              }}
            />
            
            <Button
              type="submit"
              fullWidth
              variant="contained"
              sx={{ mt: 3, mb: 2 }}
              disabled={loading}
            >
              {loading ? <CircularProgress size={24} /> : 'Sign In'}
            </Button>

            <Button
              fullWidth
              variant="outlined"
              color="primary"
              sx={{ mb: 2 }}
              onClick={fillAdminCredentials}
            >
              Use Admin Account
            </Button>

            <Stack spacing={2} sx={{ width: '100%', mt: 2 }}>
              <Button
                fullWidth
                variant="outlined"
                color="primary"
                component={RouterLink}
                to="/register"
                startIcon={<PersonAdd />}
              >
                Create New Account
              </Button>
              <Divider sx={{ my: 2 }}>or</Divider>
              <Box sx={{ textAlign: 'center' }}>
                <Link
                  component={RouterLink}
                  to="/forgot-password"
                  variant="body2"
                  sx={{ display: 'inline-block', mt: 1 }}
                >
                  Forgot password?
                </Link>
              </Box>
            </Stack>
          </Box>
        </Paper>
      </Box>
    </Container>
  );
};

export default Login;
